type AnalytifyRouteGlowsProps = {
  className?: string;
  scene?: "Library" | "Insights" | "Social" | "League";
  viewport?: "Desktop" | "Mobile";
};

export default function AnalytifyRouteGlows({ className, scene = "Library", viewport = "Desktop" }: AnalytifyRouteGlowsProps) {
  const isDesktopAndInsights = viewport === "Desktop" && scene === "Insights";
  const isDesktopAndLeague = viewport === "Desktop" && scene === "League";
  const isDesktopAndSocial = viewport === "Desktop" && scene === "Social";
  const isMobileAndInsights = viewport === "Mobile" && scene === "Insights";
  const isMobileAndLeague = viewport === "Mobile" && scene === "League";
  const isMobileAndLibrary = viewport === "Mobile" && scene === "Library";
  const isMobileAndSocial = viewport === "Mobile" && scene === "Social";
  return (
    <div className={className || `relative ${viewport === "Mobile" ? "h-[866.667px] w-[390px]" : "h-[810px] w-[1440px]"}`} id={isMobileAndLeague ? "node-607_21884" : isDesktopAndLeague ? "node-607_21881" : isMobileAndSocial ? "node-529_21503" : isMobileAndInsights ? "node-529_21488" : isMobileAndLibrary ? "node-529_21473" : isDesktopAndSocial ? "node-529_21444" : isDesktopAndInsights ? "node-529_21415" : "node-529_21386"}>
      <div className={`absolute ${isMobileAndLeague ? "inset-[-31.15%_-74.36%_-25.77%_-69.23%]" : isDesktopAndLeague ? "inset-[-46.91%_-26.39%_-50.62%_-29.86%]" : isMobileAndSocial ? "inset-[-21.85%_-63.77%_-19.85%_-52.31%]" : isMobileAndInsights ? "inset-[-13.85%_-60.31%_-15.85%_-64.77%]" : isMobileAndLibrary ? "inset-[-28.85%_-64.77%_-1.85%_-67.31%]" : isDesktopAndSocial ? "inset-[-42.81%_-27.44%_-40.81%_-8.61%]" : isDesktopAndInsights ? "inset-[-34.81%_-16.61%_-36.81%_-28.44%]" : "inset-[-49.81%_-28.44%_-22.81%_-23.61%]"}`}>
